Clear-Host; $ReportPath = Join-Path $PSScriptRoot "audit_report.txt"; if (Test-Path $ReportPath) { Clear-Content $ReportPath }; Write-Host "?? STARTING WORKSPACE SCANNER" -ForegroundColor Cyan; $PythonExecutable = if (Test-Path "env\Scripts\python.exe") { "env\Scripts\python.exe" } else { "python" }; $PythonFiles = Get-ChildItem -Path "evaluation_harness" -Filter "*.py"; $JavaScriptFiles = Get-ChildItem -Filter "*.js" | Where-Object { $PSItem.Name -ne "validate-md.js" }; $MarkdownFiles = Get-ChildItem -Filter "*.md"; if ($PythonFiles.Count -gt 0) { Write-Host "?? Processing Python Files..." -ForegroundColor Magenta; foreach ($PFile in $PythonFiles) { if ($PFile.Name -eq "eval_utils.py") { continue }; Write-Host "? Testing: $($PFile.Name)... " -NoNewline; $env:PYTHONPATH = $PSScriptRoot; $Output = & $PythonExecutable $PFile.FullName 2>&1; if ($LASTEXITCODE -eq 0 -and $Output -match "OK") { Write-Host "[PASSED]" -ForegroundColor Green } else { Write-Host "[FAILED]" -ForegroundColor Red; if ($Output -match "__EVAL_FIX_DATA__:(.*)") { if ($Matches -ne $null -and $Matches.Count -gt 1) { $JsonRaw = $Matches[1]; try { $FixData = ConvertFrom-Json $JsonRaw; Write-Host "    +- Reason: " -NoNewline -ForegroundColor Yellow; Write-Host $FixData.reason -ForegroundColor White; Write-Host "    +- Suggested Automated Correction:" -ForegroundColor Cyan; $FixData.suggested_fix -split "`n" | ForEach-Object { Write-Host "       $_" -ForegroundColor Green } } catch { Write-Host "    +- Raw Error Output: $Output" -ForegroundColor DarkGray } } else { Write-Host "    +- Raw Error Output: $Output" -ForegroundColor DarkGray } } else { Write-Host "    +- Raw Error Output: $Output" -ForegroundColor DarkGray }; $Output | Out-File -FilePath "audit_report.txt" -Append } } }; if ($JavaScriptFiles.Count -gt 0) { Write-Host "?? Processing JavaScript Files..." -ForegroundColor Yellow; foreach ($JFile in $JavaScriptFiles) { Write-Host "? Testing: $($JFile.Name)... " -NoNewline; $Output = & node $JFile.